css_variables.block:
:root {
  --color-background: #0D0D0D;
  --color-surface: #161616;
  --color-surface-raised: #1F1F1F;
  --color-border: #2C2C2C;
  --color-primary: #6366F1;
  --color-secondary: #FF6B6B;
  --color-text: #EDEDED;
  --color-text-muted: #A8A8A8;
  --color-text-inverse: #0D0D0D;
  --color-accent: #0EA5E9;
  --color-success: #10B981;
  --color-warning: #F59E0B;
  --color-danger: #FF6B6B;

  --primitive-gradient-primary: linear-gradient(135deg, #6366F1 0%, #FF6B6B 100%);
  --primitive-gradient-secondary: linear-gradient(135deg, #0EA5E9 0%, #6366F1 100%);
  --primitive-glow-primary: 0 0 48px rgba(99, 102, 241, 0.28);

  --typography-font-heading: 'Inter', 'Helvetica Neue', Arial, sans-serif;
  --typography-font-body: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --typography-font-mono: 'JetBrains Mono', 'SF Mono', Menlo, Consolas, monospace;
  --typography-font-display: 'Playfair Display', Georgia, serif;

  --slide-pad-x: 8rem;
  --slide-pad-y: 6rem;
  --radius-md: 12px;
  --radius-lg: 20px;
  --duration-base: 420ms;
  --ease-out: cubic-bezier(0.16, 1, 0.3, 1);
}
